PARAMS_TW=dict(zip(PARAMS,['樣式最終輸出的整體不透明度。','剪影內部的填滿不透明度；所有軌跡樣式預設 0.15。','向剪影外擴散的半徑，單位為螢幕像素。','柔光向外衰減的指數。','發光強度。','輪廓寬度，單位為螢幕像素。','輪廓邊緣柔化寬度，單位為像素。','輪廓外的輝光半徑，單位為像素。','輪廓外輝光的強度。','霓虹核心的 ARGB 色彩。','霓虹核心與剪影色彩的混合比例。','霓虹核心寬度，單位為像素。','霓虹泛光半徑，單位為像素。','霓虹泛光強度。','霓虹亮度脈動頻率，單位為赫茲。','霓虹亮度脈動幅度。','樣式動畫速度；保留該樣式原始單位與方向。','彩虹完成一次色相變化的螢幕距離，單位為像素。','彩虹色彩的飽和度。','彩虹與軌跡原色的混合比例。','樣式向外擴散的最大距離，單位為像素。','環或條紋之間的距離，單位為像素。','漣漪環的寬度，單位為像素。','剪影邊緣輪廓寬度，單位為像素。','全像條紋的 ARGB 色彩。','全像條紋的可見強度。','全像條紋方向角，單位為度。','全像動畫閃爍強度。','半色調圓點網格的單元大小，單位為像素。','半色調圓點相對網格的大小。','紅綠藍輪廓之間的分離距離，單位為像素。','色散輪廓與軌跡原色的混合比例。','光環向上升起的高度，單位為像素。','光環左右搖擺距離，單位為像素。','世界空間雜訊的尺度，單位為螢幕像素。','光環中心向白色變亮的比例。']))
assert len(LABELS_TW)==len(LABELS) and len(HELP_TW)==len(HELP) and len(PARAMS_TW)==len(PARAMS)
def key(path):return 'liquidbounce.module.breadcrumbs.'+'.'.join(n[0].lower()+n[1:]for n in path.split('.'))
def descriptions(language):
 source=json.loads((ROOT/f'upstream/LiquidBounce/src/main/resources/resources/liquidbounce/lang/{language}.json').read_text(encoding='utf8'));result={'liquidbounce.module.breadcrumbs.description':source['liquidbounce.module.breadcrumbs.description']}
 for path,value in (HELP_TW if language=='zh_tw'else HELP).items():result[key(path)+'.description']=value
 for style,fields in zip(NAMES,FIELDS):
  for name in ['Opacity','Fill']+fields:result[key(f'Render.Shader.Style.{style}.{name}')+'.description']=(PARAMS_TW if language=='zh_tw'else PARAMS)[name]
 if language=='en_us':
  result={k:v for k,v in source.items()if k.startswith('liquidbounce.module.breadcrumbs.')}
  result.update({key(path)+'.description':v for path,v in {'OnlyOwn':'Record only the local player, or every world player when disabled.','Color':'ARGB trail color. Shader silhouettes start opaque before age-based fading.','Rainbow':'Original HSB rainbow with a ten-second period.','Height':'Trail height in blocks; zero draws lines.','Temporary.Enabled':'Expire old trail points after Alive milliseconds.','Temporary.Alive':'Point lifetime in milliseconds; default 900, UI range 10–10000.','Temporary.Fade':'Fade points linearly by their age while Temporary is enabled.','Render':'Plain world geometry or the original nine distance-field shader styles.','Render.Shader.Style':'Choose one of the nine original post-processing styles.'}.items()})
  for style,fields in zip(NAMES,FIELDS):
   for name in ['Opacity','Fill']+fields:result[key(f'Render.Shader.Style.{style}.{name}')+'.description']=f'{name} parameter of the original {style} style; imported values retain source semantics.'
 return result
def update(language,target):
 data=json.loads(target.read_text(encoding='utf8'));data['labels'].update(LABELS if language=='zh_cn'else LABELS_TW);data['descriptions'].update(descriptions(language))
 if language=='zh_cn':data['englishDescriptions'].update(descriptions('en_us'))
 target.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--directory',required=True);a=p.parse_args()
 for language in ['zh_cn','zh_tw']:update(language,ROOT/a.directory/f'display_{language}.json')
